    # Find the solid divider, which separates two equal-sized panels.
    divider_col = next((c for c in range(w)
                        if len({grid[r][c] for r in range(h)}) == 1), None)
    if divider_col is not None:
        left = [row[:divider_col] for row in grid]
        right = [row[divider_col + 1:] for row in grid]
    else:
        divider_row = next(r for r in range(h)
                           if len(set(grid[r])) == 1)
        left = grid[:divider_row]
        right = grid[divider_row + 1:]

    counts = {}
    for row in left:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    return [[3 if left[r][c] == right[r][c] else background
             for c in range(len(left[0]))]
            for r in range(len(left))]
